+import Foundation
+import ApplicationServices
+
+func attr(_ element: AXUIElement, _ name: CFString) -> AnyObject? {
+    var value: CFTypeRef?
+    let err = AXUIElementCopyAttributeValue(element, name, &value)
+    if err != .success { return nil }
+    return value
+}
+
+let system = AXUIElementCreateSystemWide()
+if let focusedApp = attr(system, kAXFocusedApplicationAttribute) as? AXUIElement {
+    let pid = (attr(focusedApp, kAXPIDAttribute) as? NSNumber)?.intValue ?? -1
+    let name = (attr(focusedApp, kAXTitleAttribute) as? String) ?? "?"
+    print("focused app pid=\(pid) name=\(name)")
+    if let windows = attr(focusedApp, kAXWindowsAttribute) as? [AXUIElement] {
+        print("windows=\(windows.count)")
+        for (i, win) in windows.enumerated() {
+            let title = (attr(win, kAXTitleAttribute) as? String) ?? ""
+            print("window[\(i)] title=\(title)")
+        }
+    }
+}
+
+if let apps = attr(system, kAXChildrenAttribute) as? [AXUIElement] {
+    for app in apps {
+        let pid = (attr(app, kAXPIDAttribute) as? NSNumber)?.intValue ?? -1
+        let name = (attr(app, kAXTitleAttribute) as? String) ?? ""
+        if name.lowercased().contains("simulator") || name.lowercased().contains("safari") || name.lowercased().contains("element") {
+            print("app pid=\(pid) name=\(name)")
+            if let windows = attr(app, kAXWindowsAttribute) as? [AXUIElement] {
+                for (i, win) in windows.enumerated() {
+                    let title = (attr(win, kAXTitleAttribute) as? String) ?? ""
+                    print("  window[\(i)] title=\(title)")
+                }
+            }
+        }
+    }
+}
